insert into public.curated_course_resources (course_id, kind, title, link_or_site, description, sort_order)
values
  ('ca0fa381-7b19-4f9a-ae84-0d4067d7fe9c', 'textbook'::public.curated_course_resource_kind, 'University Physics Volume 2', 'https://openstax.org/details/books/university-physics-volume-2', 'OpenStax. Free calculus-based spine for charge, fields, potential, circuits, magnetism, induction, AC response, and electromagnetic waves.', 0),
  ('ca0fa381-7b19-4f9a-ae84-0d4067d7fe9c', 'textbook'::public.curated_course_resource_kind, 'University Physics Volume 3', 'https://openstax.org/details/books/university-physics-volume-3', 'OpenStax. Free continuation for geometric optics, interference, diffraction, polarization, and modern-physics bridges.', 1),
  ('ca0fa381-7b19-4f9a-ae84-0d4067d7fe9c', 'textbook'::public.curated_course_resource_kind, 'University Physics with Modern Physics', 'Pearson', 'Young and Freedman. Polished comprehensive text with strong derivations, diagrams, applications, and graded problem sequences.', 2),
  ('ca0fa381-7b19-4f9a-ae84-0d4067d7fe9c', 'textbook'::public.curated_course_resource_kind, 'Fundamentals of Physics', 'Wiley', 'Halliday, Resnick and Walker. Widely used alternative with extensive worked examples and problem practice.', 3),
  ('ca0fa381-7b19-4f9a-ae84-0d4067d7fe9c', 'textbook'::public.curated_course_resource_kind, 'Physics for Scientists and Engineers', 'Cengage', 'Serway and Jewett. Engineering-oriented calculus-based treatment of fields, circuits, waves, and optics.', 4),
  ('ca0fa381-7b19-4f9a-ae84-0d4067d7fe9c', 'textbook'::public.curated_course_resource_kind, 'Electricity and Magnetism', 'Cambridge University Press', 'Purcell and Morin. Deeper conceptual and relativistic perspective with challenging problems for honors sections.', 5),
  ('ca0fa381-7b19-4f9a-ae84-0d4067d7fe9c', 'textbook'::public.curated_course_resource_kind, 'Introduction to Electrodynamics', 'Cambridge University Press', 'David J. Griffiths. Selective later-course bridge for potentials, boundary values, fields in matter, Maxwell equations, and waves.', 6),
  ('ca0fa381-7b19-4f9a-ae84-0d4067d7fe9c', 'textbook'::public.curated_course_resource_kind, 'Optics', 'Pearson', 'Eugene Hecht. Focused enrichment for ray optics, coherence, interference, diffraction, polarization, and instruments.', 7),
  ('ca0fa381-7b19-4f9a-ae84-0d4067d7fe9c', 'website'::public.curated_course_resource_kind, 'MIT 8.02SC Physics II', 'https://ocw.mit.edu/courses/8-02sc-physics-ii-electricity-and-magnetism-fall-2010/', 'Lectures, notes, worked examples, problem sets, and exams aligned to a rigorous E&M sequence.', 8),
  ('ca0fa381-7b19-4f9a-ae84-0d4067d7fe9c', 'website'::public.curated_course_resource_kind, 'MIT 8.02X Experimental Focus', 'https://ocw.mit.edu/courses/8-02x-physics-ii-electricity-magnetism-with-an-experimental-focus-spring-2005/', 'Model for integrating experiments, circuit measurement, induction, microwaves, and wave optics with theory.', 9),
  ('ca0fa381-7b19-4f9a-ae84-0d4067d7fe9c', 'website'::public.curated_course_resource_kind, 'AAPT Goals and Laboratory Recommendations', 'https://www.aapt.org/resources/policy/goaloflabs.cfm', 'Guidance on investigation design, tools, uncertainty, modeling, collaboration, and the basis of physical knowledge.', 10),
  ('ca0fa381-7b19-4f9a-ae84-0d4067d7fe9c', 'website'::public.curated_course_resource_kind, 'PhET Interactive Simulations', 'https://phet.colorado.edu/', 'Interactive field, circuit, wave, and optics exploration for prediction and model testing.', 11),
  ('ca0fa381-7b19-4f9a-ae84-0d4067d7fe9c', 'website'::public.curated_course_resource_kind, 'Falstad Circuit Simulator', 'https://falstad.com/circuit/', 'Fast visual simulation of DC, transient, AC, resonance, and filter behavior, then compare with analytic and measured results.', 12),
  ('ca0fa381-7b19-4f9a-ae84-0d4067d7fe9c', 'website'::public.curated_course_resource_kind, 'All About Circuits Textbook', 'https://www.allaboutcircuits.com/textbook/', 'Free practical support for components, measurement, DC/AC circuits, and troubleshooting.', 13),
  ('ca0fa381-7b19-4f9a-ae84-0d4067d7fe9c', 'website'::public.curated_course_resource_kind, 'HyperPhysics Electricity and Magnetism', 'http://hyperphysics.phy-astr.gsu.edu/hbase/emcon.html', 'Fast review of relationships among E&M concepts and equations. Best used as a map, not a primary text.', 14),
  ('ca0fa381-7b19-4f9a-ae84-0d4067d7fe9c', 'youtube'::public.curated_course_resource_kind, 'MIT OpenCourseWare', 'https://www.youtube.com/@mitocw', 'University-level E&M lectures and demonstrations aligned to the main sequence.', 15),
  ('ca0fa381-7b19-4f9a-ae84-0d4067d7fe9c', 'youtube'::public.curated_course_resource_kind, 'All About Electronics', 'https://www.youtube.com/@ALLABOUTELECTRONICS', 'Clear circuit measurement, transient, AC, filter, and electronics explanations.', 16),
  ('ca0fa381-7b19-4f9a-ae84-0d4067d7fe9c', 'youtube'::public.curated_course_resource_kind, 'Michel van Biezen', 'https://www.youtube.com/@MichelvanBiezen', 'Large library of worked E&M, circuit, wave, and optics problems for deliberate practice.', 17);
